-- M1 access scope hardening
create or replace function public.current_access_profile() returns table(organization_id uuid,role_code text,scope_type text,scope_id uuid) language sql stable security definer set search_path=public as $$ select om.organization_id,r.code,mr.scope_type,mr.scope_id from organization_memberships om join membership_roles mr on mr.membership_id=om.id join roles r on r.id=mr.role_id where om.user_id=auth.uid() and om.status='ACTIVE'; $$;
revoke all on function public.current_access_profile() from public,anon; grant execute on function public.current_access_profile() to authenticated;
create or replace function public.can_access_project(target_project uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from projects p join organization_memberships om on om.organization_id=p.organization_id join membership_roles mr on mr.membership_id=om.id where p.id=target_project and om.user_id=auth.uid() and om.status='ACTIVE' and (mr.scope_type='ORGANIZATION' or (mr.scope_type='PROJECT' and mr.scope_id=target_project))); $$;
revoke all on function public.can_access_project(uuid) from public,anon; grant execute on function public.can_access_project(uuid) to authenticated;
create or replace function public.can_manage_organization(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_memberships om join membership_roles mr on mr.membership_id=om.id join roles r on r.id=mr.role_id where om.organization_id=target_org and om.user_id=auth.uid() and om.status='ACTIVE' and r.code in ('OWNER','FINANCE_MANAGER') and mr.scope_type='ORGANIZATION'); $$;
revoke all on function public.can_manage_organization(uuid) from public,anon; grant execute on function public.can_manage_organization(uuid) to authenticated;
drop policy if exists "projects_select_authenticated" on public.projects; drop policy if exists "projects_select_access" on public.projects; create policy "projects_select_scoped" on public.projects for select to authenticated using(public.can_access_project(id));